}","new_string":"/**
 * Read one snapshot file into the digests it records.
 * @param {string} path - the snapshot's workspace path, as the argument gave it.
 * @returns {Map<string, string>} the recorded digest of each path.
 * @throws {SnapshotError} when the file is unreadable or a line is malformed.
 */
export function readSnapshot(path) {
  let content
  try {
    content = readFileSync(path, 'utf8')
  } catch (error) {
    throw new SnapshotError(`cannot read snapshot ${path}`)
  }

  const lines = content.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const recorded = new Map()

  for (const [index, raw] of lines.entries()) {
    const lineNumber = index + 1
    const text = raw.trim()

    // Skip empty lines and comments
    if (text === '' || text.startsWith('#')) continue

    // Split on runs of whitespace
    const words = text.split(/\s+/u)

    // Must have exactly 2 words
    if (words.length !== 2) {
      throw new SnapshotError(`${path}: line ${lineNumber}: expected <path> <digest>`)
    }

    const [pathPart, digestPart] = words

    // Check if digest is valid (exactly 8 lowercase hex digits)
    if (!DIGEST.test(digestPart)) {
      throw new SnapshotError(`${path}: line ${lineNumber}: invalid digest ${digestPart}`)
    }

    // Check if path is recorded twice
    if (recorded.has(pathPart)) {
      throw new SnapshotError(`${path}: line ${lineNumber}: path ${pathPart} is recorded twice`)
    }

    recorded.set(pathPart, digestPart)
  }

  return recorded
}"}

